<template>
  <main class="nearby-page"><section class="search-panel"><div><span>POSTGIS SPATIAL SEARCH</span><h1>查找附近图书馆</h1><p>输入当前位置和半径，系统会在三个站点并行执行空间距离查询。</p></div><div class="coordinates"><el-input-number v-model="longitude" :precision="6" :step="0.001"/><el-input-number v-model="latitude" :precision="6" :step="0.001"/><el-select v-model="radiusKm"><el-option v-for="r in [3,5,10,20,50]" :key="r" :label="`${r} 公里内`" :value="r"/></el-select><el-button type="primary" :loading="loading" @click="search">查询附近</el-button></div></section><section class="map-results"><div class="map-wrap"><div ref="mapElement" class="map-host"></div><div class="map-note">圆形表示 {{ radiusKm }} km 查询范围</div></div><aside><header><strong>距离排序</strong><span>{{ rows.length }} RESULTS</span></header><div class="library-list"><article v-for="row in rows" :key="Number(row.library_id)" @click="focus(row)"><i></i><div><strong>{{ row.library_name }}</strong><span>Site {{ row.site_id }} · {{ row.address }}</span></div><b>{{ formatDistance(row.distance_m) }}</b></article><el-empty v-if="!loading&&!rows.length" description="范围内没有图书馆"/></div></aside></section><el-alert v-if="error" :title="error" type="error" :closable="false"/></main>
</template>
<script setup lang="ts">
import { onBeforeUnmount,onMounted,ref } from 'vue';import Map from 'ol/Map';import View from 'ol/View';import TileLayer from 'ol/layer/Tile';import VectorLayer from 'ol/layer/Vector';import VectorSource from 'ol/source/Vector';import OSM from 'ol/source/OSM';import Feature from 'ol/Feature';import Point from 'ol/geom/Point';import Circle from 'ol/geom/Circle';import { fromLonLat } from 'ol/proj';import { Circle as CircleStyle,Fill,Stroke,Style } from 'ol/style';import { apiErrorMessage,getNearbyLibraries } from '@/api/client';import type { DataRow } from '@/types'
const mapElement=ref<HTMLElement>(),longitude=ref(104.066),latitude=ref(30.67),radiusKm=ref(10),rows=ref<DataRow[]>([]),loading=ref(false),error=ref('');let map:Map|undefined;const source=new VectorSource();const layer=new VectorLayer({source,style:f=>f.get('kind')==='origin'?new Style({image:new CircleStyle({radius:8,fill:new Fill({color:'#e45757'}),stroke:new Stroke({color:'#fff',width:3})})}):f.get('kind')==='radius'?new Style({fill:new Fill({color:'rgba(12,167,154,.10)'}),stroke:new Stroke({color:'#0ca79a',width:2,lineDash:[8,6]})}):new Style({image:new CircleStyle({radius:7,fill:new Fill({color:'#087f76'}),stroke:new Stroke({color:'#fff',width:2})})})})
function draw(){source.clear();const center=fromLonLat([longitude.value,latitude.value]);source.addFeature(new Feature({geometry:new Circle(center,radiusKm.value*1000),kind:'radius'}));source.addFeature(new Feature({geometry:new Point(center),kind:'origin'}));rows.value.forEach(r=>source.addFeature(new Feature({geometry:new Point(fromLonLat([Number(r.longitude),Number(r.latitude)])),kind:'library',...r})));const extent=source.getExtent();if(extent)map?.getView().fit(extent,{padding:[45,45,45,45],maxZoom:14,duration:450})}
async function search(){loading.value=true;error.value='';try{rows.value=(await getNearbyLibraries(longitude.value,latitude.value,radiusKm.value)).rows;draw()}catch(e){error.value=apiErrorMessage(e)}finally{loading.value=false}}function focus(r:DataRow){map?.getView().animate({center:fromLonLat([Number(r.longitude),Number(r.latitude)]),zoom:15,duration:350})}function formatDistance(v:unknown){const n=Number(v);return n<1000?`${n.toFixed(0)} m`:`${(n/1000).toFixed(1)} km`}
onMounted(()=>{map=new Map({target:mapElement.value,layers:[new TileLayer({source:new OSM()}),layer],view:new View({center:fromLonLat([longitude.value,latitude.value]),zoom:11})});search()});onBeforeUnmount(()=>map?.setTarget(undefined))
</script>
<style scoped>
.nearby-page{max-width:1220px;margin:auto;padding:36px 25px 60px;color:#17364a}.search-panel{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.search-panel span{color:#078b80;font:9px 'DM Mono';letter-spacing:.14em}.search-panel h1{font-size:25px;margin:8px 0 4px}.search-panel p{font-size:10px;color:#7c9198}.coordinates{display:flex;gap:8px}.coordinates :deep(.el-input__wrapper),.coordinates :deep(.el-select__wrapper){background:#fff!important}.coordinates :deep(.el-input__inner),.coordinates :deep(.el-select__selected-item){color:#264554!important}.coordinates .el-input-number{width:135px}.map-results{height:620px;display:grid;grid-template-columns:minmax(0,1fr) 360px;background:#fff;border:1px solid #dfe9eb;border-radius:12px;overflow:hidden}.map-wrap{position:relative}.map-host{width:100%;height:100%}.map-note{position:absolute;left:14px;bottom:14px;padding:7px 10px;background:rgba(255,255,255,.92);border:1px solid #dbe7e8;border-radius:5px;color:#688087;font-size:9px}.map-results aside{border-left:1px solid #e1eaec;overflow:hidden}.map-results aside>header{height:57px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;border-bottom:1px solid #e7eef0}.map-results aside header strong{font-size:13px}.map-results aside header span{font:8px 'DM Mono';color:#81969c}.library-list{height:calc(100% - 57px);overflow:auto}.library-list article{display:flex;align-items:center;gap:10px;padding:15px;border-bottom:1px solid #edf2f3;cursor:pointer}.library-list article:hover{background:#f3faf9}.library-list i{width:8px;height:8px;border-radius:50%;background:#0b9b8f}.library-list div{flex:1;min-width:0;display:flex;flex-direction:column}.library-list strong{font-size:11px}.library-list span{font-size:8px;color:#84979d;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.library-list b{font:9px 'DM Mono';color:#078b80}@media(max-width:900px){.search-panel{align-items:flex-start;flex-direction:column;gap:15px}.coordinates{flex-wrap:wrap}.map-results{grid-template-columns:1fr;height:auto}.map-wrap{height:480px}.map-results aside{height:350px;border-left:0;border-top:1px solid #e1eaec}}
</style>
